import {characters,questions,rank,explanations,portraitSpec,portraitStyle} from './data.js';
const $=s=>document.querySelector(s),app=$('#app'),key='shinobi-designer-v1';
let answers=[],step=0,current=null,personal=false,format='story',cardBlob=null,cardRevision=0;
const orders=questions.map((_,i)=>[[2,0,3,1],[1,3,0,2],[3,1,2,0],[0,2,1,3]][i%4]);
try{const saved=JSON.parse(localStorage.getItem(key));if(Array.isArray(saved?.answers)&&saved.answers.length<=12&&saved.answers.every(a=>a===null||Number.isInteger(a)&&a>=0&&a<4)){answers=saved.answers;step=Math.max(0,Math.min(11,Number(saved.step)||0));}}catch{}
const atlas=new Image();atlas.src='assets/portraits-manga.png';
const legends=new Image();legends.src='assets/portraits-legends.png';
const portrait=c=>`<div class="portrait" role="img" aria-label="Illustration of ${c.name}" style="${portraitStyle(c)}"></div>`;
function save(){try{localStorage.setItem(key,JSON.stringify({answers,step}));}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function focusTitle(){requestAnimationFrame(()=>{const h=app.querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}window.scrollTo(0,0);});}
function home(){current=null;$('#header-note').innerHTML='<span>A quiz for designers.</span><button class="header-cta" id="header-start">Find my character &nbsp; →</button>';const resume=answers.some(Number.isInteger);app.innerHTML=`<section class="hero"><div class="hero-copy"><h1>Your design<br>process has a<br><span class="orange">Naruto</span> character.</h1><p class="intro">Discover which Naruto character shares your approach to design in 12 questions.</p><button class="primary" id="start">${resume?'Continue my test':'Find my character'} <span class="arrow" aria-hidden="true">→</span></button><p class="small">12 questions &nbsp;·&nbsp; About 3 minutes &nbsp;·&nbsp; No sign-up</p>${resume?'<button class="text-button" id="fresh">Start a new test</button>':''}</div><img class="hero-art" src="assets/hero-manga.png" alt="Naruto, Kakashi, Temari and Rock Lee in four illustrated manga panels" fetchpriority="high"></section><section class="roster"><p class="eyebrow" style="text-align:center">FIND YOUR COUNTERPART</p><h2>More than the main character.</h2><p class="roster-sub">Explore 22 different approaches to design, from familiar teammates to the Sannin and Hokage.</p><div class="roster-grid">${characters.map(c=>`<div class="roster-item">${portrait(c)}<strong>${c.name}</strong><p>${c.title.replace('The ','')}</p></div>`).join('')}</div></section>`;$('#start').onclick=()=>{if(answers.length===12&&answers.every(Number.isInteger))result(rank(answers)[0].character,true);else quiz();};if($('#fresh'))$('#fresh').onclick=reset;$('#header-start').onclick=()=>$('#start').click();}
function reset(){answers=[];step=0;save();history.replaceState(null,'',location.pathname);quiz();}
function quiz(){current=null;$('#header-note').textContent='Your next mission.';const q=questions[step];app.innerHTML=`<section class="quiz"><div class="quiz-top"><span>QUESTION ${String(step+1).padStart(2,'0')} / 12</span><div class="progress" role="progressbar" aria-label="Quiz progress" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${step}"><i style="width:${step/12*100}%"></i></div></div><p class="eyebrow">YOUR NEXT MISSION</p><h1 id="question-title">${q.title}</h1><p class="helper">Choose what you usually do, not what sounds ideal.</p><fieldset class="options" aria-labelledby="question-title"><legend class="sr-only">Choose one answer</legend>${orders[step].map((a,i)=>`<label class="option"><span class="letter" aria-hidden="true">${'ABCD'[i]}</span><span class="answer-text">${q.options[a]}</span><input type="radio" name="answer" value="${a}" aria-label="${q.options[a]}" ${answers[step]===a?'checked':''}></label>`).join('')}</fieldset><div class="quiz-nav"><button class="text-button" id="back">← ${step?'Back':'Home'}</button><button class="primary" id="next" ${Number.isInteger(answers[step])?'':'disabled'}>${step===11?'Reveal my character':'Next question'} <span aria-hidden="true">→</span></button></div></section>`;app.querySelectorAll('input').forEach(el=>el.onchange=()=>{answers[step]=Number(el.value);save();$('#next').disabled=false;});$('#back').onclick=()=>{if(step){step--;save();quiz();}else home();};$('#next').onclick=()=>{if(!Number.isInteger(answers[step]))return;if(step<11){step++;save();quiz();}else{save();result(rank(answers)[0].character,true);}};focusTitle();}
function result(c,isPersonal){current=c;personal=isPersonal;history.replaceState(null,'',`${location.pathname}?result=${c.id}`);$('#header-note').textContent='';const ranked=isPersonal?rank(answers):null;const why=isPersonal?explanations(answers,c):[];app.innerHTML=`<section class="result"><div class="result-grid"><div class="result-visual">${portrait(c)}<div class="traits">${c.traits.map(t=>`<span>${t}</span>`).join('')}</div></div><div class="result-copy"><p class="eyebrow">${isPersonal?'YOUR SHINOBI MATCH':'SHARED CHARACTER PROFILE'}</p><h1>${c.name}</h1><h2>${c.title}</h2><p class="description">${c.description}</p><h3><span>${isPersonal?'Your answers suggest':'The character connection'}</span></h3>${isPersonal?`<ul class="reasons">${why.map(t=>`<li>${t}</li>`).join('')}</ul><p class="connection" style="margin-top:16px">${c.connection}</p>`:`<p class="connection">${c.connection}</p>`}<h3><span>A possible blind spot</span></h3><p class="blind">${c.blind}</p></div></div><div class="result-actions"><button class="primary" id="share">Share ${isPersonal?'my':'this'} result <span aria-hidden="true">↗</span></button><button class="secondary" id="download">Download card ↓</button><button class="secondary" id="retake">${isPersonal?'Retake test':'Find my character →'}</button></div>${ranked&&ranked[1].distance-ranked[0].distance<=1?`<p class="close-match">A close call: your answers also lean towards <strong>${ranked[1].character.name}</strong>. Working styles overlap; this is your closest match, not a fixed identity.</p>`:''}</section>`;$('#share').onclick=openShare;$('#download').onclick=openShare;$('#retake').onclick=reset;focusTitle();}
function resultUrl(){const u=new URL(location.href);u.search='';u.hash='';u.searchParams.set('result',current.id);return u.href;}
async function openShare(){if(!current)return;$('#share-dialog').showModal();const url=resultUrl(),text=`I’m ${current.name} — ${current.title}. Which Naruto character are you as a designer?`;$('#share-x').href=`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`;$('#share-tg').href=`https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}`;await drawCard();}
function wrap(ctx,text,x,y,maxWidth,lineHeight){let line='';for(const word of text.split(' ')){const trial=line?line+' '+word:word;if(ctx.measureText(trial).width>maxWidth&&line){ctx.fillText(line,x,y);y+=lineHeight;line=word;}else line=trial;}ctx.fillText(line,x,y);return y+lineHeight;}
async function drawCard(){
 const revision=++cardRevision;cardBlob=null;$('#save-card').disabled=true;$('#native-share').disabled=true;
 try{
  const spec=portraitSpec(current),art=current.index>=14?legends:atlas;
  await Promise.all([art.decode(),document.fonts.load('80px Anton')]);if(revision!==cardRevision)return;
  const canvas=$('#card-preview'),ctx=canvas.getContext('2d'),story=format==='story';
  const W=1080,H=story?1920:1080;canvas.width=W;canvas.height=H;
  ctx.fillStyle='#f7f4ec';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#171715';ctx.lineWidth=8;ctx.strokeRect(25,25,W-50,H-50);
  ctx.textAlign='center';ctx.fillStyle='#ff681d';ctx.fillRect(325,story?100:65,430,58);ctx.fillStyle='#171715';ctx.font='bold 26px Arial';ctx.fillText('MY DESIGNER TYPE',540,story?139:104);
  const name=current.name.toUpperCase();let size=story?120:86;
  while(size>35){ctx.font=`${size}px Anton`;if(ctx.measureText(name).width<930)break;size--;}
  ctx.fillText(name,540,story?330:220);ctx.font=`${story?38:30}px Arial`;ctx.fillText(current.title,540,story?395:275);
  const artSize=story?930:570,artX=(W-artSize)/2,artY=story?460:315,cellW=art.naturalWidth/spec.cols,cellH=art.naturalHeight/spec.rows;
  ctx.drawImage(art,spec.index%spec.cols*cellW,Math.floor(spec.index/spec.cols)*cellH,cellW,cellH,artX,artY,artSize,artSize);ctx.lineWidth=4;ctx.strokeRect(artX,artY,artSize,artSize);
  ctx.fillStyle='#171715';ctx.font=`${story?48:32}px Anton`;wrap(ctx,'“'+current.quote+'”',540,story?1510:953,930,60);
  ctx.font=`${story?25:22}px Arial`;ctx.fillText(current.traits.join('   /   '),540,story?1660:1015);
  if(story){ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(80,1740);ctx.lineTo(1000,1740);ctx.stroke();ctx.font='25px Arial';ctx.fillText('Which Naruto character are you as a designer?',540,1800);ctx.font='20px Arial';ctx.fillStyle='#77746d';ctx.fillText(location.hostname,540,1850);}
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(revision!==cardRevision)return;if(!blob)throw Error();cardBlob=blob;$('#save-card').disabled=false;$('#native-share').disabled=false;
 }catch{if(revision===cardRevision)toast('The artwork could not load. Please try again.');}
}
$('#save-card').onclick=()=>{if(!cardBlob)return;const url=URL.createObjectURL(cardBlob),a=document.createElement('a');a.href=url;a.download=`shinobi-${current.id}-${format}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Your card is ready to save.');};
$('#native-share').onclick=async()=>{if(!cardBlob)return;const file=new File([cardBlob],`shinobi-${current.id}.png`,{type:'image/png'});try{if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:`${current.name} — Shinobi Designer`});else if(navigator.share)await navigator.share({title:`${current.name} — Shinobi Designer`,url:resultUrl()});else toast('Download your card or copy the result link.');}catch(e){if(e.name!=='AbortError')toast('Sharing is unavailable. Download your card instead.');}};
$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(resultUrl());toast('Result link copied.');}catch{toast('Copy the result URL from your address bar.');}};
document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{format=b.dataset.format;document.querySelectorAll('[data-format]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawCard();});
$('#about').onclick=()=>$('#info').showModal();document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('.brand').onclick=e=>{e.preventDefault();history.replaceState(null,'',location.pathname);home();};
const id=new URL(location.href).searchParams.get('result');const shared=characters.find(c=>c.id===id);if(shared)result(shared,false);else home();
